// Shared prototype behavior for every design variation.
// Not product code: it fakes the runtime (no Pyodide) and replays real traces
// generated by the VisualLeet tracer, so each design can be judged with the
// real renderer output. CSP-friendly: no inline handlers, no eval.
//
// A variation's index.html provides elements with these ids (all optional
// except #viz): example, setup, solution, call, visualize, stop, reset,
// importSelection, importLeetcode, status, message, diag, banner,
// placeholder, viz. URL ?state=<name> opens a state directly:
// ready | empty | initializing | running | complete | limit | timeout |
// stopped | syntax | import-ok | import-fail

(() => {
  const $ = (id) => document.getElementById(id);
  const BASE = new URL("../_shared/", document.currentScript.src.replace(/proto\.js.*$/, "")).href;
  let examples = {};
  let current = null;
  let rendered = null;

  const STATUS_TEXT = {
    "not-initialized": "Not initialized", initializing: "Starting Python…", ready: "Ready",
    running: "Running…", preparing: "Preparing visualization…", complete: "Complete",
    "limit-reached": "Limit reached", "timed-out": "Timed out", stopped: "Stopped", failed: "Error",
  };

  function setStatus(state) {
    const el = $("status");
    if (el) { el.dataset.state = state; el.textContent = STATUS_TEXT[state] || state; }
    document.body.dataset.status = state;
    const running = state === "running" || state === "initializing" || state === "preparing";
    if ($("visualize")) $("visualize").disabled = running;
    if ($("stop")) $("stop").disabled = state !== "running";
  }

  // Banners/messages above the trace move it; arrows are drawn once per step,
  // so redraw them after any layout change above the visualizer.
  function redrawArrows() {
    if (rendered) requestAnimationFrame(() => rendered && rendered.viz.redrawConnectors());
  }

  function setMessage(text, kind = "info") {
    const el = $("message");
    if (!el) return;
    el.textContent = text || "";
    el.dataset.kind = kind;
    el.hidden = !text;
    redrawArrows();
  }

  function setBanner(kind, title, body) {
    const el = $("banner");
    if (!el) return;
    if (!kind) { el.hidden = true; el.replaceChildren(); return; }
    el.hidden = false;
    el.dataset.kind = kind;
    const t = document.createElement("strong");
    t.textContent = title;
    const b = document.createElement("span");
    b.textContent = body ? " " + body : "";
    el.replaceChildren(t, b);
    redrawArrows();
  }

  function setPlaceholder(kind, title, body) {
    const el = $("placeholder");
    const viz = $("viz");
    if (!el) return;
    if (!kind) { el.hidden = true; if (viz) viz.hidden = false; return; }
    if (rendered) { rendered.destroy(); rendered = null; }
    if (viz) viz.hidden = true;
    el.hidden = false;
    el.dataset.kind = kind;
    const h = document.createElement("div"); h.className = "ph-title"; h.textContent = title;
    const p = document.createElement("div"); p.className = "ph-body"; p.textContent = body || "";
    const icon = document.createElement("div"); icon.className = "ph-icon"; icon.setAttribute("aria-hidden", "true");
    el.replaceChildren(icon, h, p);
  }

  function setDiag(lines) {
    if ($("diag")) $("diag").textContent = lines.join("\n");
  }

  function fillExample(key) {
    const ex = examples[key];
    current = key;
    for (const part of ["setup", "solution", "call"]) if ($(part)) $(part).value = ex[part];
    if ($("example")) $("example").value = key;
  }

  async function renderCurrent() {
    const trace = await (await fetch(BASE + "traces/" + current + ".json")).json();
    setPlaceholder(null);
    if (rendered) rendered.destroy();
    const opts = $("viz").dataset.options ? JSON.parse($("viz").dataset.options) : {};
    rendered = VisualLeetRenderer.renderTrace("viz", trace, opts);
    // land on an interesting step so the screenshot shows frames + arrows
    const target = { bfs: 20, reverse_list: 30, two_sum: 8 }[current] || 0;
    if (target) rendered.viz.renderStep(target);
    return trace;
  }

  const DIAG = (steps, kib) => [
    "Python 3.14.2 · Pyodide 314.0.8",
    `Runtime start 2.4 s · last run ${steps} steps, ${kib} KiB`,
    "execute 16 ms · render 11 ms · click → view 32 ms",
  ];

  async function visualize() {
    setBanner(null); setMessage("");
    setStatus("running");
    await new Promise((r) => setTimeout(r, 450));
    const trace = await renderCurrent();
    setStatus("complete");
    setDiag(DIAG(trace.trace.length, 46));
  }

  async function showState(state) {
    setBanner(null); setMessage("");
    switch (state) {
      case "empty":
        for (const p of ["setup", "solution", "call"]) if ($(p)) $(p).value = "";
        setStatus("ready");
        setPlaceholder("empty", "Nothing to show yet", "Paste or import a solution, add a test call, then press Visualize.");
        setDiag(["Python 3.14.2 · Pyodide 314.0.8", "Runtime start 2.4 s"]);
        break;
      case "initializing":
        setStatus("initializing");
        setPlaceholder("loading", "Starting Python…", "Loading the bundled runtime. This happens once per tab (about 2 s).");
        setDiag(["Loading Pyodide 314.0.8…"]);
        break;
      case "running":
        setStatus("running");
        setPlaceholder("loading", "Running your code…", "Recording each step. Press Stop if it takes too long.");
        break;
      case "limit": {
        const trace = await renderCurrent();
        setStatus("limit-reached");
        setBanner("warn", "Incomplete trace.", "The program hit the 1,000-step limit. Showing the steps recorded so far — try a smaller input.");
        setDiag(DIAG(trace.trace.length, 46));
        break;
      }
      case "timeout":
        setStatus("timed-out");
        setPlaceholder("error", "Stopped after 5 seconds", "The program ran too long without finishing. Python is restarting — try a smaller input.");
        break;
      case "stopped":
        setStatus("stopped");
        setPlaceholder("info", "Run stopped", "Your code is unchanged. Press Visualize to run it again.");
        break;
      case "syntax":
        setStatus("failed");
        setPlaceholder("error", "Line 4: SyntaxError: invalid syntax", "The program didn't start. Fix the highlighted line and press Visualize.");
        break;
      case "import-ok":
        await visualize();
        setMessage("Imported 9 lines of Python from the LeetCode editor into Solution.", "ok");
        break;
      case "import-fail":
        await visualize();
        setMessage("Couldn't read the LeetCode editor on this page. Select the code and use Import selection, or paste it.", "error");
        break;
      default:
        await visualize();
    }
  }

  function addSwitcher() {
    const states = ["complete", "empty", "initializing", "running", "limit", "timeout", "stopped", "syntax", "import-ok", "import-fail"];
    const box = document.createElement("div");
    box.className = "proto-switcher";
    const label = document.createElement("label");
    label.textContent = "Prototype state ";
    const sel = document.createElement("select");
    for (const s of states) { const o = document.createElement("option"); o.value = o.textContent = s; sel.appendChild(o); }
    sel.addEventListener("change", () => { fillExample(current); showState(sel.value); });
    label.appendChild(sel);
    box.append(label);
    document.body.appendChild(box);
    return sel;
  }

  async function main() {
    examples = await (await fetch(BASE + "traces/examples.json")).json();
    if ($("example")) {
      for (const [k, ex] of Object.entries(examples)) {
        const o = document.createElement("option"); o.value = k; o.textContent = ex.title; $("example").appendChild(o);
      }
      $("example").addEventListener("change", () => { fillExample($("example").value); visualize(); });
    }
    const params = new URLSearchParams(location.search);
    fillExample(params.get("example") || "bfs");
    $("visualize") && $("visualize").addEventListener("click", visualize);
    $("stop") && $("stop").addEventListener("click", () => showState("stopped"));
    $("reset") && $("reset").addEventListener("click", async () => { await showState("initializing"); setTimeout(() => showState("complete"), 900); });
    $("importSelection") && $("importSelection").addEventListener("click", () => setMessage("Imported 12 selected lines into Solution.", "ok"));
    $("importLeetcode") && $("importLeetcode").addEventListener("click", () => showState("import-ok"));
    document.querySelectorAll("[data-tab]").forEach((tab) => tab.addEventListener("click", () => {
      const group = tab.closest("[data-tabs]");
      group.querySelectorAll("[data-tab]").forEach((t) => t.setAttribute("aria-selected", String(t === tab)));
      group.querySelectorAll("[data-panel]").forEach((p) => { p.hidden = p.dataset.panel !== tab.dataset.tab; });
    }));
    document.querySelectorAll("[data-toggle]").forEach((btn) => btn.addEventListener("click", () => {
      document.body.classList.toggle(btn.dataset.toggle);
    }));
    // keep any .step-meter in sync with the visualizer's current step
    setInterval(() => {
      const meter = document.querySelector(".ws .step-meter");
      if (!meter) return;
      const v = rendered && rendered.viz;
      meter.style.visibility = v ? "visible" : "hidden";
      if (!v) return;
      const total = v.curTrace.length - 1, cur = Math.min(v.curInstr + 1, total);
      meter.querySelector("b").textContent = cur;
      meter.querySelector(".total").textContent = total;
      meter.style.setProperty("--p", (100 * cur / total).toFixed(1) + "%");
    }, 150);
    const sel = addSwitcher();
    const state = params.get("state") || "complete";
    sel.value = state;
    await showState(state);
  }

  main();
})();
